function publicCache(ttlMs = 30_000) { return (req, res, next) => { if (req.method !== 'GET') return next(); const key = cacheKey(req); const hit = responseCache.get(key); if (hit && hit.expires > Date.now()) return res.status(hit.status).set(hit.headers).send(hit.body); const send = res.send.bind(res); res.send = (body) => { if (res.statusCode >= 200 && res.statusCode < 300) responseCache.set(key, { expires: Date.now() + ttlMs, status: res.statusCode, headers: { 'Content-Type': res.get('Content-Type') || 'application/json', 'Cache-Control': `public, max-age=${Math.floor(ttlMs / 1000)}` }, body }); return send(body); }; next(); }; }
function clearPublicCache() { responseCache.clear(); }

const hashPassword = (password, salt = crypto.randomBytes(16).toString('hex')) => ({ salt, hash: crypto.scryptSync(password, salt, 64).toString('hex') });
const validPassword = (password, salt, hash) => crypto.timingSafeEqual(Buffer.from(hashPassword(password, salt).hash, 'hex'), Buffer.from(hash, 'hex'));
