app.post('/api/paystack/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  if (!verifyPaystackSignature(req)) return res.sendStatus(401);
  let event;
  try { event = JSON.parse(req.body.toString('utf8')); } catch { return res.sendStatus(400); }
  let eventKey;
  try {
    eventKey = String(event.id || event.data?.id || `${event.event}:${event.data?.reference || event.data?.transaction || 'unknown'}:${event.data?.status || ''}`);
    const inserted = (await pool.query('INSERT INTO payment_events (event_key, event_type, reference, payload) VALUES ($1, $2, $3, $4) ON CONFLICT (event_key) DO NOTHING RETURNING id', [eventKey, event.event || 'unknown', event.data?.reference || String(event.data?.transaction || ''), JSON.stringify(event)])).rows[0];
    if (!inserted) return res.sendStatus(200);
    if (event.event === 'charge.success' && event.data?.reference) await markPaid(event.data.reference, event.data);
    if (['transfer.success', 'transfer.failed', 'transfer.reversed'].includes(event.event) && event.data?.reference) { const next = event.event === 'transfer.success' ? 'success' : event.event === 'transfer.reversed' ? 'reversed' : 'failed'; await pool.query('UPDATE orders SET payout_status = $1, payout_error = $2, updated_at = NOW() WHERE payout_reference = $3', [next, next === 'success' ? null : (event.data.reason || `Paystack transfer ${next}`), event.data.reference]); await pool.query('UPDATE order_payouts SET status = $1, error = $2, updated_at = NOW() WHERE paystack_reference = $3', [next, next === 'success' ? null : (event.data.reason || `Paystack transfer ${next}`), event.data.reference]); }
    if (['refund.processed', 'refund.success', 'refund.failed'].includes(event.event)) { const reference = event.data?.reference || event.data?.transaction; const next = event.event === 'refund.failed' ? 'failed' : 'success'; await pool.query('UPDATE order_refunds SET status = $1, updated_at = NOW() WHERE paystack_reference = $2', [next, reference]); }
    res.sendStatus(200);
  } catch (error) { if (eventKey) await pool.query('DELETE FROM payment_events WHERE event_key = $1', [eventKey]).catch(() => {}); console.error(`Paystack webhook failed: ${error.message}`); res.sendStatus(500); }
});
