async function transaction(work) { const client = await pool.connect(); try { await client.query('BEGIN'); const result = await work(client); await client.query('COMMIT'); return result; } catch (error) { await client.query('ROLLBACK'); throw error; } finally { client.release(); } }
async function saveStatusHistory(client, orderId, fromStatus, toStatus, changedBy) { await client.query('INSERT INTO order_status_history (order_id, from_status, to_status, changed_by) VALUES ($1, $2, $3, $4)', [orderId, fromStatus, toStatus, changedBy || null]); }
async function transitionOrder(orderId, expected, next, changedBy, setSql = '', setParams = []) {
  return transaction(async (client) => {
    const current = (await client.query('SELECT status FROM orders WHERE id = $1 FOR UPDATE', [orderId])).rows[0];
    if (!current || current.status !== expected) return null;
    const idPlaceholder = 2 + setParams.length;
    const expectedPlaceholder = idPlaceholder + 1;
    const result = (await client.query(`UPDATE orders SET status = $1, updated_at = NOW()${setSql ? `, ${setSql}` : ''} WHERE id = $${idPlaceholder} AND status = $${expectedPlaceholder} RETURNING *`, [next, ...setParams, orderId, expected])).rows[0];
    if (result) await saveStatusHistory(client, orderId, expected, next, changedBy);
    return result;
  });
}
function validEvidenceType(value = '') { return /^image\/(jpeg|png|webp|gif)$|^video\/(mp4|quicktime|webm)$/.test(value); }
function disputeReason(value) { return ['not_done', 'not_as_agreed', 'damaged', 'wrong_item'].includes(value); }
async function ensureCustomerOrderLimit(customerId, amountKobo) {
  const completed = Number((await pool.query("SELECT COUNT(*)::int AS count FROM orders WHERE customer_id = $1 AND status = 'confirmed'", [customerId])).rows[0].count);
  const open = Number((await pool.query("SELECT COUNT(*)::int AS count FROM orders WHERE customer_id = $1 AND status IN ('requested', 'paid', 'delivered', 'disputed')", [customerId])).rows[0].count);
  const strikes = Number((await pool.query('SELECT COUNT(*)::int AS count FROM strikes WHERE user_id = $1', [customerId])).rows[0].count);
  const configuredMax = completed >= env.completedOrdersToRaiseLimit ? env.raisedCustomerMaxOrderAmount : env.newCustomerMaxOrderAmount;
  const maxAmount = (strikes >= 2 ? Math.min(configuredMax, env.twoStrikeMaxOrderAmount) : configuredMax) * 100;
  if (amountKobo > maxAmount) throw Object.assign(new Error(`This customer account can currently place orders up to ₦${(maxAmount / 100).toLocaleString()}.`), { status: 400 });
  const maxOpen = (completed >= env.completedOrdersToRaiseLimit && strikes < 2) ? env.raisedCustomerMaxOpenOrders : env.newCustomerMaxOpenOrders;
  if (open >= maxOpen) throw Object.assign(new Error('This customer has reached the maximum number of open orders.'), { status: 400 });
}

