app.post('/api/admin/artisans/:id/decision', auth, adminRequired, async (req, res) => { try { if (!['approved', 'rejected'].includes(req.body.decision)) return res.status(400).json({ message: 'Decision must be approved or rejected.' }); const result = await pool.query(`UPDATE artisans SET verification_status = $1::varchar, verification_rejection_reason = $2, verified_at = CASE WHEN $1::text = 'approved' THEN NOW() ELSE NULL END WHERE id = $3 RETURNING id, verification_status AS "verificationStatus", verification_rejection_reason AS "rejectionReason"`, [req.body.decision, req.body.decision === 'rejected' ? (req.body.reason || 'Please upload clearer verification details.') : null, req.params.id]); if (!result.rows[0]) return res.status(404).json({ message: 'Artisan not found.' }); await audit(req.user.id, `artisan_${req.body.decision}`, 'artisan', req.params.id, { reason: req.body.reason || null }); res.json({ artisan: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/disputes', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT o.id, o.description, o.amount, o.platform_fee AS "platformFee", o.artisan_amount AS "artisanAmount", o.status, o.payment_reference AS "paymentReference", o.created_at AS "createdAt", u.name AS "customerName", u.email AS "customerEmail", au.name AS "artisanName", c.id AS "conversationId", d.reason AS "disputeReason", d.explanation AS "disputeExplanation", d.appeal_deadline AS "appealDeadline", (SELECT COUNT(*)::int FROM order_proofs p WHERE p.order_id = o.id AND p.proof_type = 'artisan_completion') AS "artisanProofCount", (SELECT COUNT(*)::int FROM order_proofs p WHERE p.order_id = o.id AND p.proof_type = 'customer_dispute') AS "customerProofCount" FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users au ON au.id = a.user_id JOIN conversations c ON c.id = o.conversation_id LEFT JOIN disputes d ON d.id = o.dispute_id WHERE o.status = 'disputed' ORDER BY o.updated_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/orders/:id/messages', auth, adminRequired, async (req, res) => { try { const order = (await pool.query('SELECT o.id, o.status, o.conversation_id AS "conversationId" FROM orders o WHERE o.id = $1', [req.params.id])).rows[0]; if (!order) return res.status(404).json({ message: 'Order not found.' }); const allowed = order.status === 'disputed' || (await pool.query('SELECT 1 FROM reported_messages rm JOIN messages m ON m.id = rm.message_id WHERE m.conversation_id = $1 LIMIT 1', [order.conversationId])).rows[0]; if (!allowed) return res.status(403).json({ message: 'Admin chat access is limited to disputed or reported conversations.' }); const messages = (await pool.query('SELECT m.id, m.body, m.image_url AS "imageUrl", m.created_at AS "createdAt", u.name AS "senderName" FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.conversation_id = $1 ORDER BY m.created_at ASC', [order.conversationId])).rows; res.json({ order, messages }); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/orders/:id/resolve', auth, adminRequired, async (req, res) => { try {
  const action = req.body.action;
  if (!['release', 'fix_on_hold'].includes(action)) return res.status(400).json({ message: 'Unknown resolution.' });
  if (typeof req.body.note !== 'string' || req.body.note.trim().length < 10) return res.status(400).json({ message: 'A written decision reason of at least 10 characters is required.' });
  const result = await transaction(async (client) => {
    const order = (await client.query('SELECT * FROM orders WHERE id = $1 FOR UPDATE', [req.params.id])).rows[0];
    if (!order || order.status !== 'disputed' || (order.admin_decision && order.admin_decision !== 'fix_on_hold')) return null;
    const nextStatus = action === 'release' ? 'confirmed' : 'disputed';
    const updated = (await client.query(`UPDATE orders SET status = $1, admin_decision = $2, admin_note = $3, confirmed_at = CASE WHEN $1 = 'confirmed' THEN NOW() ELSE confirmed_at END, updated_at = NOW() WHERE id = $4 AND status = 'disputed' RETURNING *`, [nextStatus, action, req.body.note.trim(), order.id])).rows[0];
    if (nextStatus !== order.status) await saveStatusHistory(client, order.id, order.status, nextStatus, req.user.id);
    return updated;
  });
  if (!result) return res.status(409).json({ message: 'This dispute is already being resolved or has been decided.' });
  await pool.query("INSERT INTO messages (conversation_id, sender_id, body, type) VALUES ($1, $2, $3, 'text')", [result.conversation_id, req.user.id, `Admin decision: ${action.replace('_', ' ')}. ${req.body.note.trim()}`]);
  if (action === 'release') await createPayout(result);
  await audit(req.user.id, `dispute_${action}`, 'order', result.id, { note: req.body.note.trim() });
  res.json({ order: result });
} catch (error) { res.status(error.status || 500).json({ message: error.status ? error.message : databaseMessage(error) }); } });
app.post('/api/admin/disputes/:id/strike', auth, adminRequired, async (req, res) => { try { if (!['customer', 'artisan'].includes(req.body.role) || typeof req.body.reason !== 'string' || req.body.reason.trim().length < 10) return res.status(400).json({ message: 'Choose a side and provide a strike reason.' }); const dispute = (await pool.query('SELECT d.order_id, o.customer_id, a.user_id AS artisan_user_id FROM disputes d JOIN orders o ON o.id = d.order_id JOIN artisans a ON a.id = o.artisan_id WHERE d.id = $1', [req.params.id])).rows[0]; if (!dispute) return res.status(404).json({ message: 'Dispute not found.' }); const userId = req.body.role === 'customer' ? dispute.customer_id : dispute.artisan_user_id; const strike = (await pool.query('INSERT INTO strikes (user_id, order_id, dispute_id, reason, created_by) VALUES ($1, $2, $3, $4, $5) RETURNING id, created_at AS "createdAt"', [userId, dispute.order_id, req.params.id, req.body.reason.trim(), req.user.id])).rows[0]; const count = Number((await pool.query('SELECT COUNT(*)::int AS count FROM strikes WHERE user_id = $1', [userId])).rows[0].count); await pool.query('UPDATE users SET warnings = warnings + 1 WHERE id = $1', [userId]); await audit(req.user.id, 'strike_added', req.body.role, userId, { disputeId: req.params.id, count }); res.status(201).json({ strike, totalStrikes: count }); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/reviews/reported', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT r.id, r.rating, r.comment, r.customer_first_name AS "customerFirstName", r.hidden, o.id AS "orderId", u.name AS "customerName", au.name AS "artisanName", ARRAY_AGG(DISTINCT rr.reason) AS reasons FROM reviews r JOIN orders o ON o.id = r.order_id JOIN users u ON u.id = r.customer_id JOIN artisans a ON a.id = r.artisan_id JOIN users au ON au.id = a.user_id JOIN review_reports rr ON rr.review_id = r.id GROUP BY r.id, o.id, u.name, au.name ORDER BY r.created_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/reviews/:id/action', auth, adminRequired, async (req, res) => { try { const review = (await pool.query('SELECT * FROM reviews WHERE id = $1', [req.params.id])).rows[0]; if (!review) return res.status(404).json({ message: 'Review not found.' }); if (!['keep', 'hide', 'warn'].includes(req.body.action)) return res.status(400).json({ message: 'Unknown review action.' }); if (req.body.action === 'hide') await pool.query('UPDATE reviews SET hidden = TRUE, hidden_reason = $1 WHERE id = $2', [req.body.reason || 'Hidden by admin', review.id]); if (req.body.action === 'warn') await pool.query('UPDATE users SET warnings = warnings + 1 WHERE id = $1', [review.customer_id]); await audit(req.user.id, `review_${req.body.action}`, 'review', review.id, { reason: req.body.reason || null }); res.json({ message: 'Review action saved.' }); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/messages/reported', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT * FROM (SELECT rm.id, 'message' AS "reportType", rm.message_id AS "contentId", rm.reason, rm.created_at AS "createdAt", m.body, NULL::text AS "reviewComment", c.id AS "conversationId", u.name AS "reportedBy", su.name AS "contentAuthor" FROM reported_messages rm JOIN messages m ON m.id = rm.message_id JOIN conversations c ON c.id = m.conversation_id LEFT JOIN users u ON u.id = rm.reported_by LEFT JOIN users su ON su.id = m.sender_id UNION ALL SELECT rr.id, 'review' AS "reportType", rr.review_id AS "contentId", rr.reason, rr.created_at AS "createdAt", NULL::text AS body, r.comment AS "reviewComment", NULL::integer AS "conversationId", u.name AS "reportedBy", au.name AS "contentAuthor" FROM review_reports rr JOIN reviews r ON r.id = rr.review_id LEFT JOIN users u ON u.id = rr.reported_by JOIN artisans a ON a.id = r.artisan_id JOIN users au ON au.id = a.user_id) reports ORDER BY "createdAt" DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/users', auth, adminRequired, async (req, res) => { try { const term = `%${req.query.q || ''}%`; const result = await pool.query('SELECT id, name, email, phone, role, suspended, suspension_reason AS "suspensionReason", warnings, created_at AS "createdAt" FROM users WHERE name ILIKE $1 OR email ILIKE $1 OR COALESCE(phone, \'\') ILIKE $1 ORDER BY created_at DESC LIMIT 100', [term]); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/users/:id/suspension', auth, adminRequired, async (req, res) => { try { if (Number(req.params.id) === req.user.id) return res.status(400).json({ message: 'You cannot suspend your own admin account.' }); const suspended = Boolean(req.body.suspended); const result = await pool.query('UPDATE users SET suspended = $1, suspension_reason = $2 WHERE id = $3 RETURNING id, suspended, suspension_reason AS "suspensionReason"', [suspended, suspended ? (req.body.reason || 'Suspended by admin') : null, req.params.id]); if (!result.rows[0]) return res.status(404).json({ message: 'User not found.' }); if (suspended) await pool.query('DELETE FROM sessions WHERE user_id = $1', [req.params.id]); await audit(req.user.id, suspended ? 'user_suspend' : 'user_unsuspend', 'user', req.params.id, { reason: req.body.reason || null }); res.json({ user: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.delete('/api/admin/products/:id', auth, adminRequired, async (req, res) => { try { const result = await pool.query('UPDATE products SET hidden = TRUE WHERE id = $1 RETURNING id', [req.params.id]); if (!result.rows[0]) return res.status(404).json({ message: 'Product not found.' }); await audit(req.user.id, 'product_hide', 'product', req.params.id, { reason: req.body?.reason || null }); res.status(204).end(); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/payouts/failed', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT o.id, o.artisan_amount AS "artisanAmount", o.payout_error AS "payoutError", o.payout_reference AS "payoutReference", u.name AS "artisanName", u.email AS "artisanEmail" FROM orders o JOIN artisans a ON a.id = o.artisan_id JOIN users u ON u.id = a.user_id WHERE o.payout_status = 'failed' ORDER BY o.updated_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/reconciliation', auth, adminRequired, async (req, res) => { try { const result = await pool.query("SELECT id, order_id AS \"orderId\", issue_type AS \"issueType\", details, created_at AS \"createdAt\" FROM reconciliation_issues WHERE status = 'open' ORDER BY created_at DESC"); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/orders/:id/retry-payout', auth, adminRequired, async (req, res) => { try { const order = (await pool.query('SELECT * FROM orders WHERE id = $1 AND payout_status = \'failed\'', [req.params.id])).rows[0]; if (!order) return res.status(404).json({ message: 'Failed payout not found.' }); await createPayout(order); await audit(req.user.id, 'payout_retry', 'order', order.id); res.json({ order: (await pool.query('SELECT id, payout_status AS "payoutStatus", payout_error AS "payoutError", payout_reference AS "payoutReference" FROM orders WHERE id = $1', [order.id])).rows[0] }); } catch (error) { databaseError(res, error); } });

async function markPaid(reference, transaction) { const order = (await pool.query('SELECT * FROM orders WHERE payment_reference = $1', [reference])).rows[0]; if (!order) return null; if (transaction.status && transaction.status !== 'success') return order; if (transaction.currency && transaction.currency !== 'NGN') throw new Error('Paystack currency does not match the order.'); if (Number(transaction.amount) !== Number(order.amount)) throw new Error('Paystack amount does not match the order.'); const result = await transitionOrder(order.id, 'requested', 'paid', null, 'paid_at = NOW()'); return result || (await pool.query('SELECT * FROM orders WHERE id = $1', [order.id])).rows[0]; }
async function createPayout(order) { const payoutReference = order.payout_reference || `SCH_PAYOUT_${order.id}`; try { const existing = (await pool.query('SELECT status FROM order_payouts WHERE order_id = $1', [order.id])).rows[0]; if (existing && ['processing', 'success'].includes(existing.status)) return; await pool.query('INSERT INTO order_payouts (order_id, amount, paystack_reference, status) VALUES ($1, $2, $3, $4) ON CONFLICT (order_id) DO UPDATE SET status = EXCLUDED.status, error = NULL, updated_at = NOW()', [order.id, order.artisan_amount, payoutReference, 'pending']); const artisan = (await pool.query('SELECT * FROM artisans WHERE id = $1', [order.artisan_id])).rows[0]; if (!artisan?.recipient_code) { await pool.query('UPDATE orders SET payout_status = $1, payout_reference = $2, payout_error = $3, updated_at = NOW() WHERE id = $4', ['failed', payoutReference, 'Artisan payout details are not configured.', order.id]); await pool.query('UPDATE order_payouts SET status = $1, error = $2, updated_at = NOW() WHERE order_id = $3', ['failed', 'Artisan payout details are not configured.', order.id]); return; } const transfer = await paystack('/transfer', { method: 'POST', body: JSON.stringify({ source: 'balance', amount: String(order.artisan_amount), recipient: artisan.recipient_code, reason: `SkillConnect-HUB order ${order.id}`, reference: payoutReference }) }); const reference = transfer.reference || payoutReference; await pool.query('UPDATE orders SET payout_status = $1, payout_reference = $2, payout_error = NULL, updated_at = NOW() WHERE id = $3', ['processing', reference, order.id]); await pool.query('UPDATE order_payouts SET status = $1, paystack_reference = $2, error = NULL, updated_at = NOW() WHERE order_id = $3', ['processing', reference, order.id]); } catch (error) { await pool.query('UPDATE orders SET payout_status = $1, payout_reference = $2, payout_error = $3, updated_at = NOW() WHERE id = $4', ['failed', payoutReference, error.message, order.id]); await pool.query('UPDATE order_payouts SET status = $1, error = $2, updated_at = NOW() WHERE order_id = $3', ['failed', error.message, order.id]).catch(() => {}); } }
async function sendReleaseReminders() { if (!mailer) return; const rows = (await pool.query(`SELECT o.id, o.delivered_expires_at, u.email, u.name, au.name AS artisan_name, CASE WHEN o.reminder_24_sent_at IS NULL AND o.delivered_expires_at <= NOW() + INTERVAL '24 hours' THEN '24 hours' ELSE '6 hours' END AS window FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users au ON au.id = a.user_id WHERE o.status = 'delivered' AND o.delivered_expires_at IS NOT NULL AND ((o.reminder_24_sent_at IS NULL AND o.delivered_expires_at <= NOW() + INTERVAL '24 hours') OR (o.reminder_6_sent_at IS NULL AND o.delivered_expires_at <= NOW() + INTERVAL '6 hours'))`)).rows; for (const order of rows) { const column = order.window === '24 hours' ? 'reminder_24_sent_at' : 'reminder_6_sent_at'; const claimed = (await pool.query(`UPDATE orders SET ${column} = NOW() WHERE id = $1 AND ${column} IS NULL AND status = 'delivered' RETURNING id`, [order.id])).rows[0]; if (!claimed) continue; try { await mailer.sendMail({ to: order.email, subject: `Your SkillConnect-HUB payment releases in ${order.window}`, text: `Hi ${order.name.split(/\s+/)[0]}, please confirm your order or open a supported dispute. If you do nothing, payment releases automatically in ${order.window}.` }); } catch (error) { console.error(`Release reminder failed for order ${order.id}: ${error.message}`); } } }
async function autoConfirmDelivered() { await pool.query("UPDATE orders SET delivered_expires_at = delivered_at + ($1 * INTERVAL '1 hour') WHERE status = 'delivered' AND delivered_expires_at IS NULL AND delivered_at IS NOT NULL", [env.autoReleaseHours]); const rows = (await pool.query("SELECT id FROM orders WHERE status = 'delivered' AND delivered_expires_at <= NOW()")).rows; for (const row of rows) { const order = await transitionOrder(row.id, 'delivered', 'confirmed', null, 'confirmed_at = NOW()'); if (order) await createPayout(order); } }
async function reconcilePaystack() { if (!paystackSecret) return; const payments = (await pool.query("SELECT id, payment_reference, status FROM orders WHERE payment_reference IS NOT NULL AND status IN ('requested', 'paid') AND created_at > NOW() - INTERVAL '30 days' LIMIT 100")).rows; for (const order of payments) { try { const data = await paystack(`/transaction/verify/${encodeURIComponent(order.payment_reference)}`); if (data.status === 'success' && order.status === 'requested') await markPaid(order.payment_reference, data); if (data.status !== 'success' && order.status === 'paid') await pool.query("INSERT INTO reconciliation_issues (order_id, issue_type, details) VALUES ($1, 'paid_not_confirmed', $2) ON CONFLICT DO NOTHING", [order.id, `Paystack reports ${data.status || 'unknown'} for a locally paid order.`]); } catch (error) { await pool.query("INSERT INTO reconciliation_issues (order_id, issue_type, details) VALUES ($1, 'payment_check_failed', $2) ON CONFLICT DO NOTHING", [order.id, error.message]); } } await pool.query("INSERT INTO reconciliation_issues (order_id, issue_type, details) SELECT id, 'payout_stuck', 'Payout has been processing for more than 24 hours.' FROM orders WHERE payout_status = 'processing' AND updated_at < NOW() - INTERVAL '24 hours' ON CONFLICT DO NOTHING"); }
async function sendReviewReminders() { if (!mailer) return; const rows = (await pool.query(`SELECT o.id, u.email, u.name, auser.name AS artisan_name FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users auser ON auser.id = a.user_id LEFT JOIN reviews r ON r.order_id = o.id WHERE o.status = 'confirmed' AND o.confirmed_at <= NOW() - INTERVAL '24 hours' AND o.review_reminder_sent_at IS NULL AND r.id IS NULL`)).rows; for (const order of rows) { try { await mailer.sendMail({ from: process.env.SMTP_FROM || process.env.SMTP_USER, to: order.email, subject: 'How was your SkillConnect-HUB order?', text: `Hi ${order.name.split(/\s+/)[0]}, how was your order from ${order.artisan_name}? Leave a review in SkillConnect-HUB.` }); await pool.query('UPDATE orders SET review_reminder_sent_at = NOW() WHERE id = $1', [order.id]); } catch (error) { console.error(`Review reminder failed for order ${order.id}: ${error.message}`); } } }
setInterval(() => { sendReleaseReminders().catch((error) => console.error(`Release reminder scan failed: ${error.message}`)); autoConfirmDelivered().catch((error) => console.error(`Automatic confirmation failed: ${error.message}`)); }, 5 * 60 * 1000).unref();
setInterval(() => reconcilePaystack().catch((error) => console.error(`Paystack reconciliation failed: ${error.message}`)), 30 * 60 * 1000).unref();
setInterval(() => sendReviewReminders().catch((error) => console.error(`Review reminder scan failed: ${error.message}`)), 60 * 60 * 1000).unref();

async function ensureAdmin() { if (!process.env.ADMIN_EMAIL || !process.env.ADMIN_PASSWORD) return; const { salt, hash } = hashPassword(process.env.ADMIN_PASSWORD); await pool.query(`INSERT INTO users (name, email, password_hash, password_salt, role, email_verified, phone_verified) VALUES ('Administrator', LOWER($1), $2, $3, 'admin', TRUE, TRUE) ON CONFLICT (email) DO UPDATE SET role = 'admin', password_hash = EXCLUDED.password_hash, password_salt = EXCLUDED.password_salt, email_verified = TRUE, phone_verified = TRUE, suspended = FALSE`, [process.env.ADMIN_EMAIL, hash, salt]); console.log(`Admin account ready: ${process.env.ADMIN_EMAIL}`); }
async function anonymizeDueAccounts() { const users = (await pool.query("SELECT id FROM users WHERE deletion_requested_at <= NOW() - INTERVAL '7 days' AND anonymized_at IS NULL AND role <> 'admin'")).rows; for (const user of users) await transaction(async (client) => { const { salt, hash } = hashPassword(newToken()); await client.query("UPDATE users SET name = 'Deleted user', email = $1, phone = NULL, password_hash = $2, password_salt = $3, email_verified = FALSE, phone_verified = FALSE, anonymized_at = NOW() WHERE id = $4", [`deleted-${user.id}@deleted.invalid`, hash, salt, user.id]); await client.query("UPDATE artisans SET skill = 'Deleted', area = 'Deleted', bio = NULL, image_url = NULL, bank_name = NULL, bank_code = NULL, account_number = NULL, recipient_code = NULL, verification_id_ciphertext = NULL, verification_id_photo_url = NULL, verification_selfie_url = NULL WHERE user_id = $1", [user.id]); await client.query("UPDATE products SET name = 'Deleted product', description = NULL, image_url = 'https://res.cloudinary.com/demo/image/upload/v1/placeholder.png', hidden = TRUE WHERE artisan_id IN (SELECT id FROM artisans WHERE user_id = $1)", [user.id]); await client.query('DELETE FROM sessions WHERE user_id = $1', [user.id]); }); }
pool.on('error', (error) => console.error(`PostgreSQL pool error: ${error.message}`));
app.use((error, _req, res, _next) => { console.error(error); res.status(500).json({ message: databaseMessage(error) }); });
async function start() {
  try {
    await pool.query('SELECT 1');
    await runMigrations();
    await anonymizeDueAccounts();
    await ensureAdmin();
    console.log('PostgreSQL connected and schema is ready.');
  } catch (error) {
    console.error(`Database connection failed: ${databaseMessage(error)} Detail: ${error.message}`);
  }
  app.listen(port, () => console.log(`SkillConnect-HUB API running on port ${port}`));
}
start();
setInterval(() => anonymizeDueAccounts().catch((error) => console.error(`Scheduled account anonymization failed: ${error.message}`)), 60 * 60 * 1000).unref();
